# Seed script for the Odoo 19 test instance (JSON-2 API tests), executed via `odoo shell` (variable `env` is provided).
# Creates a fixed API key for admin, so tests know it in advance, and a few partners to query.
from odoo.addons.base.models.res_users import KEY_CRYPT_CONTEXT, INDEX_SIZE

# Fixed test key - 40 hex chars like keys generated by Odoo. Only for the local test instance!
TEST_API_KEY = "a1b2c3d4e5f60718293a4b5c6d7e8f9001234567"

admin = env.ref("base.user_admin")


def section(name):
    def wrap(fn):
        try:
            with env.cr.savepoint():
                fn()
            print(f"[seed] OK   {name}")
        except Exception as e:  # keep seeding other sections
            print(f"[seed] FAIL {name}: {e!r}")
        return fn
    return wrap


@section("api key for admin")
def _api_key():
    # same insert as res.users.apikeys._generate, but with a known key
    env.cr.execute(
        "DELETE FROM res_users_apikeys WHERE user_id = %s AND name = %s", [admin.id, "json2-tests"])
    env.cr.execute(
        """INSERT INTO res_users_apikeys (name, user_id, scope, expiration_date, key, index)
           VALUES (%s, %s, %s, %s, %s, %s)""",
        ["json2-tests", admin.id, None, None, KEY_CRYPT_CONTEXT.hash(TEST_API_KEY), TEST_API_KEY[:INDEX_SIZE]])


@section("partners")
def _partners():
    Partner = env["res.partner"]
    for name, code in [("Test Partner PL", "PL"), ("Test Partner BE", "BE"), ("Test Partner US", "US")]:
        if not Partner.search_count([("name", "=", name)]):
            Partner.create({
                "name": name,
                "is_company": True,
                "country_id": env["res.country"].search([("code", "=", code)], limit=1).id,
                "email": f"{name.lower().replace(' ', '.')}@example.com",
            })


env.cr.commit()
print("[seed] committed")
